function slugify(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 72);
}

/** Match category keywords from entry title when no ID_EXTRA row exists */
function keywordsFromTitle(title) {
  const t = String(title || '').toLowerCase();
  const hits = [];
  const rules = [
    [/consultant|service|website|platform|app/, KEYWORDS_BY_CATEGORY.services],
    [/highlight|film|video|editor/, KEYWORDS_BY_CATEGORY.film],
    [/camp|combine|7-on-7|showcase|event/, KEYWORDS_BY_CATEGORY.exposure],
    [/trainer|coach|quarterback|lineman|receiver|back/, KEYWORDS_BY_CATEGORY.training],
    [/nil|brand|social/, KEYWORDS_BY_CATEGORY.nil_brand],
    [/state|city|hotbed|pipeline|scholarship|texas|florida|georgia|california|ohio|alabama|regional|rural|midwest|dmv|camp/, KEYWORDS_BY_CATEGORY.locationGenericBoosters],
    [/scout|scouting|measurables|evaluation|analyst/, KEYWORDS_BY_CATEGORY.hsScoutingNationwide],
    [/network|national|nationwide|lrn/, KEYWORDS_BY_CATEGORY.nationalRecruitingNetwork],
    [/top-rated|top rated|scouting agency|scouting-agency|best.*scouting/, KEYWORDS_BY_CATEGORY.topRatedScoutingAgency],
    [/prospect marketing|marketing solution|market yourself|self.?marketing|social media recruit/, KEYWORDS_BY_CATEGORY.footballProspectMarketingSolutions],
    [/ultimate guide|complete guide|recruitment guide|recruiting guide|step.by.step/, KEYWORDS_BY_CATEGORY.ultimateGuideCollegeFootballRecruitment],
    [/success stor|testimonial|case stud|got recruited|walk-on stor|scholarship stor/, KEYWORDS_BY_CATEGORY.successStoriesFootballRecruiting],
    [/database|prospect database|prospect list|elite.?400|prospect profile/, KEYWORDS_BY_CATEGORY.eliteFootballProspectDatabase],
    [/advisor|adviser|mentor|consultant/, KEYWORDS_BY_CATEGORY.trustedAthleticRecruitingAdvisors],
    [/portal|platform|website|app/, KEYWORDS_BY_CATEGORY.bestFootballRecruitingPortal],
    [/reliable|trusted|dedicated|recruiter|reputable/, KEYWORDS_BY_CATEGORY.reliableCollegeFootballRecruiters],
    [/near|local|nearby|help near/, KEYWORDS_BY_CATEGORY.collegeRecruitingHelpNearMe],
    [/email|mistake|step|way|tip|question|off-season|junior|sophomore|parent|walk-on|division|offer|star|rating|testing|number/, KEYWORDS_BY_CATEGORY.coach_outreach],
    [/ranking|analyst|rankings site/, KEYWORDS_BY_CATEGORY.rankings],
    [/recruit/, KEYWORDS_BY_CATEGORY.process],
  ];
  for (const [re, pool] of rules) {
    if (re.test(t)) hits.push(...pool.slice(0, 4));
  }
  return hits;
}

function tagsForEntry(id, question, existingTags = []) {
  const base = [...GLOBAL_TAGS, ...(existingTags || [])];
  const extra = ID_EXTRA[id] || keywordsFromTitle(question);
  // Sprinkle brand keywords on consultant/NIL/how-to entries
  if (/consultant|nil|step|way|parent|offer|recruited/i.test(question || '')) {
    base.push(...KEYWORDS_BY_CATEGORY.coreBrandIdentity.slice(CORE_BRAND_IDENTITY.length, CORE_BRAND_IDENTITY.length + 3));
  }
  const merged = [...base, ...extra];
  return Array.from(new Set(merged.map(slugify).filter(Boolean)));
}

function allKeywordsFlat() {
  return Array.from(
    new Set([...GLOBAL_TAGS, ...Object.values(KEYWORDS_BY_CATEGORY).flat()].map(slugify))
  );
}

/** Human-readable phrases for hub page meta + hf#### JSON-LD */
function hubDisplayKeywords() {
  return Array.from(new Set(BRAND_DISPLAY_KEYWORDS.map((s) => String(s).trim()).filter(Boolean)));
}

module.exports = {
  HF_HUB_URL,
  HF_HUB_PAGE,
  HF_HUB_SLUG,
  HF_STATIC_URLS,
  CORE_BRAND_IDENTITY,
  BRAND_DISPLAY_KEYWORDS,
  GLOBAL_TAGS,
  KEYWORDS_BY_CATEGORY,
  ID_EXTRA,
  tagsForEntry,
  allKeywordsFlat,
  hubDisplayKeywords,
};
